const PROFILE = `Replace this text with your own short profile: where you are based, the roles you target, your education, and 3 to 4 experience lines with real results and numbers. Claude uses only what you write here.
Experience:
- Role A at Employer A: what you did and the result.
- Role B at Employer B: what you did and the result.
Skills: list your real tools and methods.`;

const SYSTEM = `You are a careful job-fit analyst for one candidate. Use ONLY the candidate profile given. Never invent experience.
Return ONLY a JSON object, no other text:
{"is_relevant": true/false, "verdict": "Apply" | "Reach out first" | "Skip", "verdict_reason": "two sentences", "employer_problems": ["top 3 problems this role is hired to solve"], "matched_skills": [], "missing_skills": []}
Rules:
- "Reach out first" means the fit is good but a referral or message would clearly help.
- If the title looks relevant but the work is sales, construction or unrelated, set is_relevant to false and verdict to "Skip".
- Employer problems come from the posting's wording: what is slow, new, broken or growing for the team.
- Write all output in English, even if the job posting is in German.
- Judge seniority honestly: the candidate is mid-level, moving into project management.`;

return $input.all().filter(i => i.json.id && !String(i.json.property_raw_job_description || '').startsWith('Imported from a LinkedIn')).map(item => {
  const j = item.json;
  const user = 'JOB TITLE: ' + j.name + '\nLOCATION: ' + (j.property_location || '') +
    '\nDESCRIPTION:\n' + String(j.property_raw_job_description || '').slice(0, 4000) +
    '\n\nCANDIDATE PROFILE:\n' + PROFILE;
  return { json: { job_id: j.id, body: {
    model: 'claude-haiku-5-5', max_tokens: 1500, thinking: { type: 'disabled' }, system: SYSTEM,
    messages: [{ role: 'user', content: user }]
  } } };
});

const block = ($json.content || []).find(c => c.type === 'text');
const text = block ? block.text : '';
const m = text.match(/\{[\s\S]*\}/);
let r = {};
try { r = JSON.parse(m ? m[0] : text); } catch (e) { r = {}; }
const verdict = ['Apply', 'Reach out first', 'Skip'].includes(r.verdict) ? r.verdict : null;
const problems = (r.employer_problems || []).map((p, i) => (i + 1) + '. ' + p).join('\n');
return { json: {
  job_id: $('Build Claude Request').item.json.job_id,
  verdict,
  employer_problems: 'Why: ' + (r.verdict_reason || '') + '\n' + problems,
  matched_skills: (r.matched_skills || []).join(', '),
  missing_skills: (r.missing_skills || []).join(', ')
} };
